/* Orange — a chromatic palette, hue ~55. Distinct from danger (hue ~25) so
   the two never read as the same state, and distinct from warning's former
   hue 65: 55 reads as orange rather than amber. Both themes declare all six
   roles. */

:root[data-theme="light"] .palette-orange {
    --palette-base: oklch(0.68 0.17 55);
    --palette-soft: oklch(0.94 0.08 70);
    --palette-line: oklch(0.85 0.12 70);
    --palette-contrast: oklch(0.2 0.05 55);
    --palette-accent: oklch(0.45 0.15 55);
    --palette-ring: var(--palette-accent);
}

:root[data-theme="dark"] .palette-orange {
    --palette-base: oklch(0.75 0.16 55);
    --palette-soft: oklch(0.3 0.08 55);
    --palette-line: oklch(0.4 0.1 55);
    --palette-contrast: oklch(0.12 0.02 55);
    --palette-accent: oklch(0.8 0.14 55);
    --palette-ring: var(--palette-accent);
}
